import{_ as n,H as s,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"04｜架构设计（上）：应用架构与代码组织","description":"","frontmatter":{},"headers":[{"level":2,"title":"应用架构：模块化单体","slug":"应用架构-模块化单体","link":"#应用架构-模块化单体","children":[]},{"level":2,"title":"Spring 代码组织规范","slug":"spring-代码组织规范","link":"#spring-代码组织规范","children":[]},{"level":2,"title":"外部调用设计","slug":"外部调用设计","link":"#外部调用设计","children":[]},{"level":2,"title":"写进CLAUDE.md","slug":"写进claude-md","link":"#写进claude-md","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/04｜架构设计（上）：应用架构与代码组织.md","filePath":"ClaudeCode企业级全链路开发实战/04｜架构设计（上）：应用架构与代码组织.md","lastUpdated":1779815375000}'),l={name:"ClaudeCode企业级全链路开发实战/04｜架构设计（上）：应用架构与代码组织.md"};function i(t,a,o,c,r,d){return s(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="_04-架构设计-上-应用架构与代码组织" tabindex="-1">04｜架构设计（上）：应用架构与代码组织 <a class="header-anchor" href="#_04-架构设计-上-应用架构与代码组织" aria-label="Permalink to &quot;04｜架构设计（上）：应用架构与代码组织&quot;">​</a></h1><p>你好，我是Robert。</p><p>上一讲我们定义了Hify的产品边界和技术栈。这一讲回答一个更具体的问题： <strong>代码怎么组织、外部调用怎么处理</strong>？</p><p>很多工程师拿到需求直接开始写代码，写到一半发现模块之间耦合得死死的、线程池被LLM调用占满了管理页面打不开、不同模块的代码风格完全不一样。这些问题不是写代码的问题，是动手之前没想清楚应用架构。</p><p><strong>这一讲和下一讲合起来是 Hify 的完整架构设计</strong>。这一讲（上篇）聚焦代码层面——模块怎么分、Spring代码怎么组织、外部调用怎么处理。下一讲（下篇）聚焦系统层面——怎么部署、瓶颈在哪、未来怎么扩展、数据怎么存。</p><h2 id="应用架构-模块化单体" tabindex="-1">应用架构：模块化单体 <a class="header-anchor" href="#应用架构-模块化单体" aria-label="Permalink to &quot;应用架构：模块化单体&quot;">​</a></h2><p>第一个问题：一个Spring Boot应用，内部怎么组织？</p><p><a href="https://time.geekbang.org/column/article/963507" target="_blank" rel="noreferrer">第03讲</a> 已经确定了一期50人单机部署。但单机不等于所有代码堆在一个package里。我让Claude Code给方案：</p><blockquote><p>Hify是一个Spring Boot单体应用，功能包括模型提供商管理、Agent配置、对话引擎、知识库RAG、简版工作流、MCP工具接入。一个人开发，一期50人使用，但后续可能要扩到几千人。代码内部怎么组织？给我方案对比。</p></blockquote><p>Claude Code给了三个方案：</p><ul><li><p>方案A：按package分层。所有功能放在一个模块里，按controller/service/mapper分package。最简单，但所有功能混在一起，后面代码量大了找文件费劲，想拆分也拆不动。</p></li><li><p>方案B：Maven多模块，按功能拆。一个Spring Boot应用，内部按Maven多模块组织，每个功能一个模块。模块之间通过接口调用，代码层面严格隔离。后续想拆分成微服务，只需要把接口调用改成远程调用，模块内部不用动。</p></li><li><p>方案C：微服务。每个功能一个独立服务，通过网关路由，服务间Feign调用。</p></li></ul><p><strong>它推荐了方案 C，理由是方便独立扩展</strong>。</p><p>我追问：</p><blockquote><p>一个人维护六七个微服务，每个要独立部署、独立配置、独立监控，精力消耗会不会太大？</p></blockquote><p>它承认了，说一人开发建议方案B。我的判断： <strong>选方案 B，模块化单体</strong>。一个人维护一个应用比维护六七个微服务轻松太多。但代码上做好模块隔离，后续需要拆分时成本可控。</p><p>最终的模块划分：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hify/</span></span>
<span class="line"><span>├── hify-app/               # 启动模块，Spring Boot Application</span></span>
<span class="line"><span>├── hify-provider/           # 模型提供商管理</span></span>
<span class="line"><span>├── hify-agent/              # Agent 管理与配置</span></span>
<span class="line"><span>├── hify-chat/               # 对话引擎</span></span>
<span class="line"><span>├── hify-mcp/                # MCP 工具管理与调用</span></span>
<span class="line"><span>├── hify-workflow/           # 工作流编排与执行</span></span>
<span class="line"><span>├── hify-knowledge/          # 知识库与 RAG</span></span>
<span class="line"><span>├── hify-common/             # 公共模块（工具类、常量、异常、DTO）</span></span>
<span class="line"><span>├── hify-web/                # Vue 前端</span></span>
<span class="line"><span>└── deploy/                  # Docker Compose 配置</span></span></code></pre></div><p>模块之间的依赖关系需要想清楚。我让Claude Code分析：</p><blockquote><p>基于 Hify 的功能，帮我梳理这些模块之间的依赖关系。谁依赖谁？有没有循环依赖的风险？</p></blockquote><p>它给的分析：hify-chat是依赖最多的模块——对话时要读Agent配置（依赖hify-agent）、调模型（依赖hify-provider）、可能走工作流（依赖hify-workflow）、可能做RAG检索（依赖hify-knowledge）、可能调工具（依赖hify-mcp）。hify-agent依赖hify-mcp（Agent要绑工具）和hify-knowledge（Agent要绑知识库）。所有模块依赖hify-common。</p><p>关键原则： <strong>依赖是单向的，不能循环。 hify-chat 可以依赖 hify-agent，但 hify-agent 不能反过来依赖hify-chat。如果出现循环依赖，说明模块边界划错了，需要把共用的部分下沉到 hify-common</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/964066/b9a900cc1131d947324f3f0a2bc4e7yy.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/964066/b9a900cc1131d947324f3f0a2bc4e7yy.jpg" alt=""></a></p><h2 id="spring-代码组织规范" tabindex="-1">Spring 代码组织规范 <a class="header-anchor" href="#spring-代码组织规范" aria-label="Permalink to &quot;Spring 代码组织规范&quot;">​</a></h2><p>这一节很多人觉得没必要讲，Controller、Service、Mapper三层架构，谁不知道？</p><p>人写代码确实不需要讲。你凭经验和习惯，自然知道业务逻辑放Service里、Controller只做参数校验。但AI不知道。你不告诉它规矩，它可能把事务管理写在Controller里、把数据库查询写在DTO里、直接引用另一个模块的Mapper把两个模块焊死。</p><p>这些规范不是写给人看的，是写给Claude Code看的。后面每一行代码都是它生成的，这些规矩定不好，生成出来的代码越多越乱。</p><p>我让Claude Code帮我梳理：</p><blockquote><p>Hify是模块化单体，用Spring Boot + MyBatis-Plus。帮我定义代码组织规范，覆盖：每个模块内部的分层结构、每一层的职责边界、跨模块调用的规则。要求具体到AI能直接执行，不要模糊的描述。</p></blockquote><p>它给了一版，我调整后定稿（这里为了省篇幅，在一些较简单的场景就不贴Claude的输出了，后面在实操课统一演示），每个业务模块内部统一结构：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/main/java/com/hify/{module}/</span></span>
<span class="line"><span>├── controller/        # REST 接口</span></span>
<span class="line"><span>├── service/           # 业务逻辑接口</span></span>
<span class="line"><span>├── service/impl/      # 业务逻辑实现</span></span>
<span class="line"><span>├── mapper/            # MyBatis-Plus Mapper</span></span>
<span class="line"><span>├── entity/            # 数据库实体</span></span>
<span class="line"><span>├── dto/               # 请求/响应对象</span></span>
<span class="line"><span>├── config/            # 配置类</span></span>
<span class="line"><span>├── exception/         # 模块级自定义异常</span></span>
<span class="line"><span>└── constant/          # 模块级常量</span></span></code></pre></div><p>每一层的职责边界：</p><ul><li><p>Controller只做两件事：参数校验和调用Service。不写业务逻辑、不做数据查询、不处理事务。为什么要这么严格？因为Claude Code特别喜欢在Controller里“顺手”加逻辑，它觉得方便，但你后面测试、重构、拆分全部受影响。</p></li><li><p>Service处理所有业务逻辑，包括事务管理、数据校验、业务规则。Service之间可以互相调用，但只能调接口（interface），不能直接new实现类。</p></li><li><p>Mapper只做数据库操作。不要在Mapper的XML里写业务逻辑（比如复杂的条件判断），那是Service的事。</p></li><li><p>Entity和数据库表一一对应。DTO是给接口用的请求/响应对象。Entity和DTO之间要做转换，不要把Entity直接返回给前端——Entity里可能有敏感字段（API Key），DTO可以控制暴露哪些字段。</p></li></ul><p>跨模块调用规则： <strong>这条是模块化单体最关键的规范。模块之间只能通过Service接口调用，不能直接引用另一个模块的Mapper、Entity或内部类</strong>。</p><p>为什么？ <strong>因为我们选模块化单体的一个重要理由是“后续能拆分”</strong>。如果hify-chat直接引用了hify-agent的Mapper，两个模块就焊死了——拆分时你要把所有这种引用找出来改成远程调用。但如果只通过Service接口调用，拆分时只需要把本地调用改成HTTP/RPC调用，接口签名都不用变。</p><p>我追问Claude Code：</p><blockquote><p>如果有一天要把hify-chat拆成独立服务，按照这套规范，改动量大概多大？</p></blockquote><p>它分析了一下：Service接口不变，实现类里的本地调用改成Feign调用，加上网络异常处理。每个跨模块调用点改两三行代码。改动量可控。</p><p>这就验证了这套规范的合理性。这里我标注下，能考虑到未来的拆分主要靠的是自己的项目经验，我希望你可以记下这个，就当积累一个经验。</p><h2 id="外部调用设计" tabindex="-1">外部调用设计 <a class="header-anchor" href="#外部调用设计" aria-label="Permalink to &quot;外部调用设计&quot;">​</a></h2><p>Hify最大的技术挑战不在CRUD，在外部LLM调用。第03讲运维预期已经指出： <strong>瓶颈不在并发，在 LLM 长连接占用线程</strong>。这一节把这个问题的解决方案定下来。</p><p>LLM API调用有三个特点：慢（一次对话3-30秒）、不稳定（随时可能超时、限流、报错）、多供应商（每家行为不一样）。不提前设计好，上线就炸。</p><p>我让Claude Code系统性地分析：</p><blockquote><p>Hify要调用多个外部LLM API（OpenAI、Claude、Gemini、Ollama），这些调用慢且不稳定。从线程管理、容错、超时、重试四个维度，给出完整的技术方案。</p></blockquote><p>它给的方案很全面，我逐个判断：</p><ol><li><p>线程池隔离——同意。LLM调用必须用独立线程池，不能和Tomcat的业务线程池共用。第03讲分析过：50个并发SSE连接，每个持续10-30秒，如果共用线程池，管理页面的请求排在队列里等，用户看到的就是页面一直转圈。独立线程池解决这个问题——对话请求用自己的池子，管理请求用Tomcat默认的池子，互不影响。</p></li><li><p>熔断机制——同意。某个LLM提供商连续失败时，快速熔断，后续请求直接返回错误，不浪费时间等超时。Claude Code建议Resilience4j，每个提供商独立熔断器——OpenAI挂了不影响Claude。合理。</p></li><li><p>超时控制——同意，但我追问了细节。它建议对话接口60秒超时，连通性测试10秒。我追问：流式响应场景下，一个SSE连接可能持续一两分钟，60秒会不会把正常对话切断？它调整了：SSE连接超时设120秒，普通同步调用60秒。合理。</p></li><li><p>重试策略——同意，细节有价值。不是所有失败都值得重试。网络抖动重试有意义，认证失败重试没用（重试一百次还是认证失败），限流需要退避重试（等一等再试）。按异常类型区分重试策略，这个细节Claude Code给得很好。</p></li></ol><p>我又追问了一个它没主动提到的问题：</p><blockquote><p>流式响应用SSE，Spring MVC怎么处理？需不需要引入WebFlux？</p></blockquote><p>它建议WebFlux做异步非阻塞。我不同意——第03讲已经确定不引入额外技术栈。SSE场景用Spring MVC的SseEmitter就够，配合独立线程池和120秒超时，50人完全能扛。不为了“技术上更优雅”引入一套新的编程模型。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/964066/2fe40123318d21b0ffecf53d8eda11fa.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/964066/2fe40123318d21b0ffecf53d8eda11fa.jpg" alt=""></a></p><h2 id="写进claude-md" tabindex="-1">写进CLAUDE.md <a class="header-anchor" href="#写进claude-md" aria-label="Permalink to &quot;写进CLAUDE.md&quot;">​</a></h2><p>这一讲的所有决策写进CLAUDE.md：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## 架构设计</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 应用架构</span></span>
<span class="line"><span>模块化单体。一个 Spring Boot 应用，Maven 多模块组织。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>模块划分：</span></span>
<span class="line"><span>- hify-provider：模型提供商管理</span></span>
<span class="line"><span>- hify-agent：Agent 管理与配置</span></span>
<span class="line"><span>- hify-chat：对话引擎</span></span>
<span class="line"><span>- hify-mcp：MCP 工具管理与调用</span></span>
<span class="line"><span>- hify-workflow：工作流编排与执行</span></span>
<span class="line"><span>- hify-knowledge：知识库与 RAG</span></span>
<span class="line"><span>- hify-common：公共模块</span></span>
<span class="line"><span></span></span>
<span class="line"><span>依赖原则：单向依赖，不循环。共用逻辑下沉 hify-common。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 代码组织</span></span>
<span class="line"><span>每个业务模块统一结构：controller / service / mapper / entity / dto / config</span></span>
<span class="line"><span></span></span>
<span class="line"><span>分层规则：</span></span>
<span class="line"><span>- Controller 只做参数校验和调用 Service，不写业务逻辑</span></span>
<span class="line"><span>- Service 处理所有业务逻辑，包括事务管理</span></span>
<span class="line"><span>- 跨模块调用走 Service 接口，不直接引用其他模块的 Mapper 或 Entity</span></span>
<span class="line"><span>- Entity 不直接返回给前端，用 DTO 做转换</span></span>
<span class="line"><span></span></span>
<span class="line"><span>### 外部调用处理</span></span>
<span class="line"><span>- LLM 调用使用独立线程池，和业务请求隔离</span></span>
<span class="line"><span>- Resilience4j 熔断，每个提供商独立熔断器</span></span>
<span class="line"><span>- 同步调用 60s 超时，SSE 流式 120s 超时，连通性测试 10s</span></span>
<span class="line"><span>- 按异常类型区分重试：网络抖动重试、认证失败不重试、限流退避重试</span></span>
<span class="line"><span>- 流式响应使用 SseEmitter + 独立线程池，不引入 WebFlux</span></span></code></pre></div><p>到这里，CLAUDE.md包含了项目概述（第03讲）和应用架构（本讲）。Claude Code对代码怎么写、放在哪、外部调用怎么处理已经有了完整的约束。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这一讲做了三件事：确定了模块化单体的应用架构，定义了Spring代码组织规范，设计了外部调用处理方案。</p><p>回顾整个过程，最有价值的不是最终方案，而是和Claude Code的追问环节。它推荐微服务，被我用“一个人维护太重”否决了。它建议WebFlux，被我用“不增加技术栈复杂度”否决了。它给的超时时间对SSE不够用，被我追问后调整了。</p><p>每一次追问的背后，都是你在用项目的真实约束来修正AI的通用建议。AI给的是技术上最优的方案，你要基于约束选对你最优的方案。这两者经常不一样。</p><p>还有一点值得强调：代码组织规范看起来是常识，但对AI写代码来说是刚需。人凭习惯知道Controller不写业务逻辑，AI不知道。你不告诉它，它就按自己的理解来，而且每次理解都不一样。这些规范现在花半小时定好，后面几百次代码生成都受益。</p><p>到这里，你可能会说我没有架构知识，不知道要问什么问题。那我想说，你以前没有，当看完这节课不就有了吗？你或者可以把这节课当作一个实践的架构课。记下来我们怎么思考的，以后就有经验了，知道怎么问问题了。</p><p>所以你在学这节课的时候得去思考我为什么这么问。而作为你自己，你会想到这么问吗？如果你不会这么问，那么就记住，以后这么问。这就是我说的方法论。</p><p>下一讲继续架构设计下篇——部署架构、性能瓶颈预判、扩展方案、数据模型。从代码层面进入系统层面。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>看看你手头正在做的项目，问自己两个问题：</p><ol><li><p>你的模块之间是通过接口调用还是直接引用内部类？如果要把某个模块拆成独立服务，改动量大概多大？</p></li><li><p>你的外部调用（数据库、第三方 API、消息队列）有没有做线程池隔离？如果某个外部服务卡了30秒，你的系统会怎样？</p></li></ol><p>结合这两个问题让Claude Code帮你分析一下你当前项目的情况。</p><p>期待你的分享。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,66)])])}const u=n(l,[["render",i]]);export{g as __pageData,u as default};
